do $$ begin if not exists(select 1 from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname='gov_repo' and t.typname='incident_status') then create type gov_repo.incident_status as enum ('reported','investigating','mitigated','resolved','closed'); end if; end $$;
do $$ begin if not exists(select 1 from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname='gov_repo' and t.typname='provider_service_type') then create type gov_repo.provider_service_type as enum ('cloud_infrastructure','foundation_model_api','saas_platform','data_provider','managed_service'); end if; end $$;
do $$ begin if not exists(select 1 from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname='gov_repo' and t.typname='ai_system_lifecycle') then create type gov_repo.ai_system_lifecycle as enum ('concept','development','testing','pre_market_review','conformity_assessed','production','under_significant_modification','post_market_surveillance','decommissioned'); end if; end $$;
create table if not exists gov_repo.ai_systems(system_id uuid primary key default uuid_generate_v4(),system_code varchar(20) not null,name varchar(255) not null,description text not null,intended_purpose text not null,risk_class gov_repo.ai_act_risk_class not null default 'minimal',status gov_repo.system_status not null default 'development',owner_user_id uuid not null references gov_repo.governance_users(user_id),business_domain varchar(100),eu_ai_db_registered boolean not null default false,eu_ai_db_ref varchar(100),conformity_assessment_id uuid references gov_repo.conformity_assessments(assessment_id),organisation_id uuid not null references gov_repo.organisations(organisation_id),ledger_entry_seq bigint references gov_repo.governance_ledger(entry_sequence),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint ai_systems_code_org_unique unique(system_code,organisation_id));
create index if not exists idx_ai_systems_org on gov_repo.ai_systems(organisation_id);
do $$ begin if not exists(select 1 from information_schema.table_constraints where constraint_schema='gov_repo' and table_name='agents' and constraint_name='fk_agent_ai_system') then alter table gov_repo.agents add constraint fk_agent_ai_system foreign key(ai_system_id) references gov_repo.ai_systems(system_id); end if; end $$;
alter table gov_repo.ai_systems enable row level security;
create table if not exists gov_repo.third_party_providers(provider_id uuid primary key default uuid_generate_v4(),provider_code varchar(20) not null,name varchar(255) not null,service_type gov_repo.provider_service_type not null,dora_criticality gov_repo.dora_criticality not null default 'medium',headquarters_country varchar(2) not null,data_processing_regions text[] not null default '{}',status varchar(30) not null default 'active' check(status in ('under_review','active','suspended','terminated')),contract_ref varchar(100),contract_expires_at date,exit_plan_documented boolean not null default false,concentration_risk_score numeric(4,2),organisation_id uuid not null references gov_repo.organisations(organisation_id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint providers_code_org_unique unique(provider_code,organisation_id));
create index if not exists idx_third_party_org on gov_repo.third_party_providers(organisation_id);
do $$ begin if not exists(select 1 from information_schema.columns where table_schema='gov_repo' and table_name='agent_resource_links' and column_name='provider_id') then alter table gov_repo.agent_resource_links add column provider_id uuid references gov_repo.third_party_providers(provider_id); end if; end $$;
alter table gov_repo.third_party_providers enable row level security;
create table if not exists gov_repo.ict_incidents(incident_id uuid primary key default uuid_generate_v4(),incident_code varchar(20) not null,title varchar(255) not null,description text not null,severity gov_repo.incident_severity not null,status gov_repo.incident_status not null default 'reported',impacted_system_ids uuid[] not null default '{}',impacted_agent_ids uuid[] not null default '{}',impacted_provider_ids uuid[] not null default '{}',downtime_minutes integer default 0,financial_impact_eur numeric(12,2) default 0,data_breach_involved boolean not null default false,root_cause text,remediation_plan text,reported_at timestamptz not null default now(),resolved_at timestamptz,reported_by uuid references gov_repo.governance_users(user_id),organisation_id uuid not null references gov_repo.organisations(organisation_id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint ict_incidents_code_org_unique unique(incident_code,organisation_id));
create index if not exists idx_ict_incidents_org on gov_repo.ict_incidents(organisation_id);
alter table gov_repo.ict_incidents enable row level security;
alter table gov_repo.ai_systems add column if not exists lifecycle gov_repo.ai_system_lifecycle not null default 'development',add column if not exists serious_incidents_reported integer not null default 0,add column if not exists last_serious_incident_at timestamptz;;
